import re, sys, json

path = sys.argv[1]
text = open(path, encoding='utf-8', errors='replace').read().splitlines()

block_re = re.compile(r'StatsLogger INFO: Epoch (\d+)/(\d+) Step (\d+)/(\d+) Train step (\d+)/(\d+) done')
# table row: │ key │ value │ key │ value ...
row_re = re.compile(r'│([^│]+)│([^│]+)│')

blocks = []
cur = None
for line in text:
    m = block_re.search(line)
    if m:
        if cur: blocks.append(cur)
        cur = {'epoch': int(m.group(1)), 'estep': int(m.group(3)), 'step': int(m.group(5)), 'metrics': {}}
        continue
    if cur:
        for mm in row_re.finditer(line):
            k = mm.group(1).strip(); v = mm.group(2).strip()
            if not k: continue
            try:
                cur['metrics'][k] = float(v)
            except ValueError:
                pass
if cur: blocks.append(cur)

keys = sys.argv[2].split(',') if len(sys.argv) > 2 else None
for b in blocks:
    out = {'ep': b['epoch'], 'es': b['estep'], 'step': b['step']}
    for k in keys or []:
        if k in b['metrics']:
            out[k] = b['metrics'][k]
    print(json.dumps(out))

