cd /tmp/diag && python3 -I - <<'EOF' > keys.txt
import sys,re,json,collections
p='/user/user1/autorlbench-runs/20261117150059-6929-1ec5/workspace/run/experiments/logs/user/kt-seeds/kpop-s2/main.log'
text=open(p,encoding='utf-8',errors='replace').read().splitlines()
block_re=re.compile(r'StatsLogger INFO: Epoch (\d+)/(\d+) Step (\d+)/(\d+) Train step (\d+)/(\d+) done')
row_re=re.compile(r'│([^│]+)│([^│]+)(?=│)')
cur=None;blocks=[]
for line in text:
    m=block_re.search(line)
    if m:
        if cur:blocks.append(cur)
        cur={'ep':int(m.group(1)),'es':int(m.group(3)),'step':int(m.group(5)),'m':{}}
        continue
    if cur:
        for mm in row_re.finditer(line):
            k=mm.group(1).strip();v=mm.group(2).strip()
            if not k:continue
            try:cur['m'][k]=float(v)
            except:pass
if cur:blocks.append(cur)
json.dump(blocks,open('/tmp/diag/all.json','w'))
c=collections.Counter()
for b in blocks:
    for k in b['m']: c[k]+=1
print(len(blocks),'blocks;',len(c),'keys;', len(blocks[0]['m']),'per block')
for k,n in sorted(c.items()): print(n,k)
EOF
